<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
foreach(['from'=>$from,'to'=>$to] as $value){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)||strtotime($value)===false){http_response_code(422);exit('Invalid report date.');}}
if($from>$to){http_response_code(422);exit('The start date must be on or before the end date.');}
$stmt=db()->prepare("SELECT DATE(created_at) AS order_date,COUNT(*) AS order_count,SUM(CASE WHEN payment_status='paid' THEN total ELSE 0 END) AS paid_revenue,SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending FROM orders WHERE created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY DATE(created_at) ORDER BY order_date");
$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="yucca-sales-report-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Date','Orders','Paid revenue','Pending orders']);foreach($rows as $row)fputcsv($out,[$row['order_date'],$row['order_count'],$row['paid_revenue'],$row['pending']]);fclose($out);exit;}
$summary=db()->prepare("SELECT COUNT(*) AS order_count,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total ELSE 0 END),0) AS revenue,COALESCE(SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END),0) AS pending FROM orders WHERE created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY)");$summary->execute([$from,$to]);$totals=$summary->fetch();
$inventory=db()->query('SELECT name,sku,stock FROM products WHERE is_active=1 AND stock<=5 ORDER BY stock,name')->fetchAll();$adminTitle='Reports · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Reports</h1><form class="mt-6 flex flex-wrap items-end gap-3 bg-white p-5"><label class="text-sm">From<input class="form-control mt-1" type="date" name="from" value="<?= e($from) ?>" required></label><label class="text-sm">To<input class="form-control mt-1" type="date" name="to" value="<?= e($to) ?>" required></label><button class="rounded-full bg-forest px-5 py-3 text-sm text-white">Apply dates</button><a class="rounded-full border border-forest px-5 py-3 text-sm" href="?<?= e(http_build_query(['from'=>$from,'to'=>$to,'export'=>'csv'])) ?>">Export CSV</a></form><div class="mt-6 grid gap-4 sm:grid-cols-3"><?php foreach([['Orders',(int)$totals['order_count']],['Paid revenue',money($totals['revenue'])],['Pending orders',(int)$totals['pending']]] as [$label,$value]): ?><article class="bg-white p-5"><p class="text-xs uppercase tracking-widest text-gray-500"><?= e($label) ?></p><p class="mt-3 font-serif text-2xl"><?= e((string)$value) ?></p></article><?php endforeach; ?></div><section class="mt-6 overflow-x-auto bg-white p-5"><h2 class="font-serif text-2xl">Sales by day</h2><table class="mt-4 w-full min-w-[500px] text-left text-sm"><thead class="text-xs uppercase text-gray-500"><tr><th class="py-3">Date</th><th>Orders</th><th>Paid revenue</th><th>Pending</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr class="border-t border-black/5"><td class="py-3"><?= e($row['order_date']) ?></td><td><?= (int)$row['order_count'] ?></td><td><?= e(money($row['paid_revenue'])) ?></td><td><?= (int)$row['pending'] ?></td></tr><?php endforeach; ?></tbody></table></section><section class="mt-6 bg-white p-5"><h2 class="font-serif text-2xl">Low stock (5 or fewer)</h2><?php if(!$inventory): ?><p class="mt-3 text-sm text-gray-600">No active products are currently low on stock.</p><?php else: ?><div class="mt-3 divide-y"><?php foreach($inventory as $item): ?><p class="flex justify-between py-3 text-sm"><span><?= e($item['name']) ?> <small class="text-gray-500"><?= e($item['sku']) ?></small></span><strong><?= (int)$item['stock'] ?></strong></p><?php endforeach; ?></div><?php endif; ?></section>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
